// SHIM FOR LEGACY GLOBALS
window.KNOWN_ITEMS = {};
window.furnitureSizes = {};
window.spritePivots = {};
window.ROTATION_MAP = {};

for (let id in window.ITEMS_DB) {
    let item = window.ITEMS_DB[id];
    if (item.furn_name) window.KNOWN_ITEMS['FURN_' + id] = item.furn_name;
    if (item.item_name) window.KNOWN_ITEMS['ITEM_' + id] = item.item_name;
    if (item.crop_name) window.KNOWN_ITEMS['CROP_' + id] = item.crop_name;
    if (item.fish_name) window.KNOWN_ITEMS['FISH_' + id] = item.fish_name;
    
    if (item.width !== undefined && item.length !== undefined) {
        window.furnitureSizes[id] = { width: item.width, length: item.length };
    }
    if (item.pivot) window.spritePivots[id] = item.pivot;
    if (item.rotations) window.ROTATION_MAP[id] = item.rotations;
}

window.getFurnitureSize = function(itemId) {
    if (window.furnitureSizes && window.furnitureSizes[itemId]) {
        return window.furnitureSizes[itemId];
    }
    return { width: 1, length: 1 };
};
